<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Illuminate\Validation\Rule;
final class AdminRoleManagementController extends Controller {
 private function requireSuperAdmin(Request $request): void {abort_unless(DB::table('rt_user_roles as ur')->join('rt_roles as r','r.id','=','ur.role_id')->where('ur.user_id',$request->user()->id)->whereNull('ur.company_id')->where('r.portal','admin')->where('r.code','super_admin')->exists(),403);}
 public function index(){return view('admin.access.roles',['roles'=>DB::table('rt_roles')->where('portal','admin')->orderBy('code')->get(),'permissions'=>DB::table('rt_permissions')->orderBy('code')->get(),'assigned'=>DB::table('rt_role_permissions')->get()->groupBy('role_id')]);}
 public function store(Request $request){$this->requireSuperAdmin($request);$data=$request->validate(['code'=>['required','regex:/^[a-z][a-z0-9_]{2,79}$/','unique:rt_roles,code'],'description'=>['nullable','string','max:1000']]);DB::transaction(function()use($data,$request){$id=(string)Str::uuid();DB::table('rt_roles')->insert(['id'=>$id,'code'=>$data['code'],'portal'=>'admin','description'=>$data['description']??null,'created_at'=>now()]);DB::table('rt_admin_audit_logs')->insert(['actor_user_id'=>$request->user()->id,'action'=>'admin_role.created','target_type'=>'role','target_id'=>$id,'details'=>json_encode(['code'=>$data['code']]),'created_at'=>now()]);});return back()->with('success','Role created.');}
 public function update(Request $request,string $role){$this->requireSuperAdmin($request);$r=DB::table('rt_roles')->where('id',$role)->where('portal','admin')->first();abort_unless($r,404);abort_if($r->code==='super_admin',403,'Super Admin role is protected.');$data=$request->validate(['description'=>['nullable','string','max:1000'],'permission_ids'=>['sometimes','array'],'permission_ids.*'=>['uuid','distinct']]);$ids=$data['permission_ids']??[];if(DB::table('rt_permissions')->whereIn('id',$ids)->count()!==count($ids)) return back()->withErrors(['permission_ids'=>'Invalid permission selection.']);DB::transaction(function()use($request,$r,$data,$ids){DB::table('rt_roles')->where('id',$r->id)->update(['description'=>$data['description']??null]);DB::table('rt_role_permissions')->where('role_id',$r->id)->delete();foreach($ids as $id)DB::table('rt_role_permissions')->insert(['role_id'=>$r->id,'permission_id'=>$id]);DB::table('rt_admin_audit_logs')->insert(['actor_user_id'=>$request->user()->id,'action'=>'admin_role.permissions_updated','target_type'=>'role','target_id'=>$r->id,'details'=>json_encode(['permission_ids'=>$ids]),'created_at'=>now()]);});return back()->with('success','Role permissions updated.');}
}
